dtsPropsFor.UiButton:
children?: React.ReactNode;
/** Fires with the press event, extended with `loader()` / `stopLoader()` when `enableLoader` is used. */
onPress: (event?: UiButtonClickEvent) => void;
/** Outlined treatment instead of the filled accent fill. */
secondary?: boolean;
/** Start in the spinner state; the button is disabled while loading. */
enableLoader?: boolean;
/** React Native StyleProp<ViewStyle>. */
style?: object;

dtsPropsFor.UiTitle:
children?: React.ReactNode;
/** 14px. */
sizeXS?: boolean;
/** 16px. */
sizeS?: boolean;
/** 20px. */
sizeM?: boolean;
/** 28px. */
sizeL?: boolean;
/** React Native StyleProp<TextStyle>. */
style?: object;
numberOfLines?: number;

dtsPropsFor.UiToast:
/** React Native StyleProp<ViewStyle>. */
style?: object;
/** Imperative handle: `ref.current.show(message, 'success' | 'error')`. */
ref?: React.Ref<{ show: (message: string, type: 'success' | 'error') => void }>;

dtsPropsFor.UiPage:
children?: React.ReactNode;
/** Intended to add a 60px top offset, but currently inert: the component's style array ends with `paddingTop: insets.top`, which overrides it either way. Defaults to true. */
indented?: boolean;

dtsPropsFor.UiPopup:
children?: React.ReactNode;
/** Fill the viewport height rather than hugging its content. Defaults to true. */
fullScreen?: boolean;
title?: string;

dtsPropsFor.UiFormField:
children: React.ReactNode;
/** Rendered under the field when set. */
errorMessage?: string;

dtsPropsFor.UiInput:
value: string;
onChange: (value: string) => void;
placeholder?: string;
/** Mask the value and show the reveal toggle. */
isSecureText?: boolean;
readonly?: boolean;

dtsPropsFor.UiTextArea:
value: string;
onChange: (value: string) => void;
placeholder?: string;
/** Defaults to 4. */
numberOfLines?: number;

dtsPropsFor.UiSelect:
options: { label: string; value: string }[];
value: string | undefined;
onChange: (value: string | undefined) => void;
/** When false (default), tapping the active chip deselects it. */
required?: boolean;
/** Lay the chips out in one horizontally scrolling row. */
horizontal?: boolean;

dtsPropsFor.ItemPickerSheet:
items: {
  id: number;
  name: string;
  img_url?: string;
  [key: string]: unknown;
}[];
selectedIds: number[];
/** Defaults to 'Select items'. */
title?: string;
/** Defaults to a live '<n> selected' count. */
subtitle?: string;
/** Defaults to a live 'Confirm <n> items' label. */
confirmLabel?: string;
hideHeader?: boolean;
onSelectionChange?: (ids: number[]) => void;
onConfirm: (ids: number[]) => void;

dtsPropsFor.OutfitSuggestionCard:
suggestion: {
  id: string;
  sessionId: string;
  sessionTopic: string;
  summary: string;
  wardrobeItemIds: number[];
  createdAt: string;
};
/** Up to 4 render; the rest collapse into a `+n` badge. Null entries show the placeholder glyph. */
thumbnails: (string | null | undefined)[];
/** Null entries render as 'Deleted item'. */
itemNames?: (string | null | undefined)[];
onPress: () => void;
/** Omit to hide the delete affordance. */
onDelete?: () => void;
